-- Testbench of vtx_announce against a simple A/R model of the SC-01.
-- Checks that the sequencer writes exactly the bus bytes of sim/votrax/stimuli/t6_version.txt
-- (generated by tools/gen_announce.py for the same BOARD_ID / SW_MINOR) and then goes idle.
-- The speech itself is not simulated here: votrax_sc01 is bit exact to the C model
-- (run_sim.ps1), and t6_version.txt rendered by ref_votrax is what it will say.
-- Run: sim/votrax/run_announce_tb.ps1

library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use std.textio.all;

entity tb_vtx_announce is
	generic (
		BOARD_ID : natural := 3;
		SW_MINOR : natural := 98;
		STIMULUS : string  := "t6_version.txt"
	);
end tb_vtx_announce;

architecture sim of tb_vtx_announce is
	signal clk   : std_logic := '0';
	signal rst_n : std_logic := '0';
	signal start : std_logic := '0';
	signal ar    : std_logic := '1';
	signal busy  : std_logic;
	signal stb   : std_logic;
	signal data  : std_logic_vector(7 downto 0);
	signal done  : boolean := false;

	type byte_arr is array (0 to 255) of std_logic_vector(7 downto 0);
	signal got   : byte_arr;
	signal n_got : natural := 0;

	function hex2(s : string) return std_logic_vector is
		variable v : natural := 0;
		variable c : character;
	begin
		for i in s'range loop
			c := s(i);
			v := v * 16;
			if c >= '0' and c <= '9' then v := v + character'pos(c) - character'pos('0');
			else v := v + character'pos(c) - character'pos('A') + 10; end if;
		end loop;
		return std_logic_vector(to_unsigned(v, 8));
	end function;
begin
	clk <= not clk after 10 ns when not done;

	DUT: entity work.vtx_announce
	generic map (BOARD_ID => BOARD_ID, SW_MINOR => SW_MINOR)
	port map (clk => clk, rst_n => rst_n, start => start, ar => ar,
	          busy => busy, stb => stb, data => data);

	-- SC-01 A/R model: takes a byte after stb was high for 3 clocks, A/R low 100 clocks
	-- later, phoneme "done" another 500 clocks later
	sc01: process
		variable hi : natural;
	begin
		wait until rising_edge(clk);
		if stb = '1' then
			hi := 0;
			while stb = '1' loop
				hi := hi + 1;
				wait until rising_edge(clk);
			end loop;
			assert hi >= 3 report "stb shorter than 3 clocks" severity failure;
			got(n_got) <= data;     -- data still valid one clock after stb
			n_got <= n_got + 1;
			for i in 1 to 100 loop wait until rising_edge(clk); end loop;
			ar <= '0';
			for i in 1 to 500 loop wait until rising_edge(clk); end loop;
			ar <= '1';
		end if;
	end process;

	main: process
		file f       : text;
		variable l   : line;
		variable w   : string(1 to 3);
		variable tok : string(1 to 2);
		variable ok  : boolean;
		variable exp : byte_arr;
		variable n_exp : natural := 0;
		variable errors : natural := 0;
	begin
		-- expected bytes: the "say" line of the stimulus
		file_open(f, STIMULUS, read_mode);
		while not endfile(f) loop
			readline(f, l);
			if l'length > 4 and l(1 to 4) = "say " then
				read(l, w);                      -- "say"
				loop
					read(l, tok(1), ok); exit when not ok;   -- blank
					read(l, tok, ok); exit when not ok;
					exp(n_exp) := hex2(tok);
					n_exp := n_exp + 1;
				end loop;
			end if;
		end loop;
		file_close(f);

		wait for 100 ns; rst_n <= '1';
		wait for 100 ns;
		wait until rising_edge(clk); start <= '1';
		wait until rising_edge(clk); start <= '0';
		wait until rising_edge(clk);
		assert busy = '1' report "not busy after start" severity failure;
		wait until busy = '0' for 200 ms;
		assert busy = '0' report "still busy" severity failure;
		wait for 1 us;

		if n_got /= n_exp then
			report "bytes written: " & integer'image(n_got) & ", expected " & integer'image(n_exp) severity error;
			errors := errors + 1;
		end if;
		for i in 0 to n_exp - 1 loop
			if i < n_got and got(i) /= exp(i) then
				report "byte " & integer'image(i) & ": got " & integer'image(to_integer(unsigned(got(i))))
				       & ", expected " & integer'image(to_integer(unsigned(exp(i)))) severity error;
				errors := errors + 1;
			end if;
		end loop;
		if errors = 0 then
			report "vtx_announce OK: " & integer'image(n_got) & " phonemes as in " & STIMULUS;
		else
			report "vtx_announce FAILED, " & integer'image(errors) & " errors" severity failure;
		end if;
		done <= true;
		wait;
	end process;
end sim;
